#include <stdio.h>
int sumTo(int n){if(!n)return 0;return n+sumTo(n-1);}
int main(void){int n;if(scanf("%d",&n)!=1)return 1;printf("sum=%d\n",sumTo(n));return 0;}

recursive-sum-gold.main.c:
#include <stdio.h>
int sumTo(int n){if(!n)return 0;return n+sumTo(n-1);}
int squaresTo(int n){if(!n)return 0;return n*n+squaresTo(n-1);}
int main(void){int n;if(scanf("%d",&n)!=1)return 1;printf("sum=%d squares=%d\n",sumTo(n),squaresTo(n));return 0;}
